function filterByDate(evs,d){if(d==="all")return evs;const td=new Date("2025-02-26");return evs.filter(e=>{const ed=new Date(e.date);if(d==="today")return ed.toDateString()===td.toDateString();if(d==="tmrw"){const t=new Date(td);t.setDate(td.getDate()+1);return ed.toDateString()===t.toDateString();}if(d==="week"){const e2=new Date(td);e2.setDate(td.getDate()+7);return ed>=td&&ed<=e2;}if(d==="wknd")return ed>=new Date("2025-02-28")&&ed<=new Date("2025-03-02");if(d==="next"){const s=new Date(td);s.setDate(td.getDate()+7);const e2=new Date(s);e2.setDate(s.getDate()+7);return ed>=s&&ed<=e2;}return true;});}
function filterByTime(evs,start,end){if(!start&&!end)return evs;return evs.filter(e=>{const h=parseInt(e.time);const pm=e.time.includes("PM");const hr=pm&&h!==12?h+12:(!pm&&h===12?0:h);if(start&&hr<start)return false;if(end&&hr>end)return false;return true;});}

// ═══ COMPONENTS ═══
function LogoIcon({size=40}){return(<img src={LOGO_ICON} alt="" style={{width:size,height:size,objectFit:"contain",flexShrink:0}}/>);}
function LogoWord({height=28}){return(<img src={LOGO_WORD} alt="fluttrr" style={{height,objectFit:"contain"}}/>);}
function Input({label,value,onChange,placeholder,type="text",icon,multi}){const[f,setF]=useState(false);const El=multi?"textarea":"input";return(<div style={{marginBottom:16}}>{label&&<label style={{display:"block",fontSize:13,fontWeight:600,color:T.muted,marginBottom:6}}>{label}</label>}<div style={{...S.row,gap:10,padding:"14px 16px",borderRadius:T.r.md,border:`1.5px solid ${f?T.blue:T.border}`,background:T.surface,alignItems:multi?"flex-start":"center"}}>{icon&&<span style={{fontSize:16,opacity:.5}}>{icon}</span>}<El type={type} value={value||""} onChange={onChange} placeholder={placeholder} rows={multi?3:undefined} onFocus={()=>setF(true)} onBlur={()=>setF(false)} style={{flex:1,background:"transparent",border:"none",outline:"none",color:T.text,fontSize:15,fontFamily:T.font,resize:"none"}}/></div></div>);}
function Btn({children,onClick,variant="primary",full=true,disabled,loading,icon,small}){const st={primary:{background:T.blue,color:"#fff",border:"none"},secondary:{background:T.surface,color:T.text,border:`1.5px solid ${T.border}`},outline:{background:"transparent",color:T.blue,border:`1.5px solid ${T.blue}`},danger:{background:T.danger,color:"#fff",border:"none"}};return(<button onClick={disabled||loading?undefined:onClick} style={{...(st[variant]||st.primary),padding:small?"10px 16px":"15px 24px",fontSize:small?13:15,width:full?"100%":"auto",borderRadius:T.r.md,fontWeight:600,fontFamily:T.font,cursor:disabled?"default":"pointer",opacity:disabled?.5:1,...S.center,gap:8}}>{loading?<div style={{width:18,height:18,border:"2px solid #fff3",borderTop:"2px solid #fff",borderRadius:"50%",animation:"spin .8s linear infinite"}}/>:icon&&<span>{icon}</span>}{children}</button>);}
function NavHeader({title,onBack,right}){return(<div style={{...S.row,justifyContent:"space-between",padding:"10px 20px",minHeight:44}}>{onBack?<button onClick={onBack} style={{background:"none",border:"none",color:T.blue,fontSize:28,cursor:"pointer",padding:0,lineHeight:1}}>‹</button>:<div style={{width:28}}/>}<span style={{fontSize:17,fontWeight:600,color:T.text}}>{title}</span>{right||<div style={{width:28}}/>}</div>);}
function Toast({message}){if(!message)return null;return(<div style={{position:"absolute",top:60,left:20,right:20,zIndex:999,background:T.card,border:`1px solid ${T.blue}`,borderRadius:T.r.md,padding:"12px 16px",...S.row,gap:8,animation:"slideDown .3s",boxShadow:"0 8px 32px rgba(0,0,0,.3)"}}><div style={{width:8,height:8,borderRadius:4,background:T.blue}}/><span style={{fontSize:14,color:T.text,fontWeight:500}}>{message}</span></div>);}
function BG({children,color=T.blue}){return(<span style={{background:`${color}22`,color,fontSize:11,fontWeight:600,padding:"2px 8px",borderRadius:6}}>{children}</span>);}
function Avatar({emoji,size=40,bg=T.surface,ring}){return(<div style={{width:size,height:size,borderRadius:size/2,background:bg,...S.center,fontSize:size*.5,flexShrink:0,border:ring?`2px solid ${ring}`:"none"}}>{emoji}</div>);}
function Toggle({on,onToggle}){return(<div onClick={e=>{e.stopPropagation();onToggle();}} style={{width:44,height:24,borderRadius:12,padding:2,background:on?T.blue:T.border,cursor:"pointer",flexShrink:0}}><div style={{width:20,height:20,borderRadius:10,background:"#fff",transform:on?"translateX(20px)":"translateX(0)",transition:"all .2s"}}/></div>);}
function PeopleAvatars({ppl,max=4,size=24}){return(<div style={{display:"flex",alignItems:"center"}}>{ppl.slice(0,max).map((p,i)=>(<div key={i} style={{width:size,height:size,borderRadius:size/2,background:T.surface,border:`2px solid ${T.card}`,marginLeft:i?-6:0,...S.center,fontSize:size*.45,zIndex:max-i}}>{p.av}</div>))}{ppl.length>max&&<span style={{fontSize:11,color:T.muted,marginLeft:4}}>+{ppl.length-max}</span>}</div>);}
function EventMilestone({count}){const m=[1,5,10,25,50,100].filter(x=>count>=x);return(<span style={{fontSize:18,fontWeight:700,color:T.blue}}>{m.length?`${m[m.length-1]}+`:"0"}</span>);}
function SpotsLabel({spots,total}){if(spots===null||total===null)return(<span style={{fontSize:12,color:T.cyan}}>No Limit ∞</span>);return(<span style={{fontSize:12,color:spots<=5?T.warn:T.success}}>{spots} spots left</span>);}
function MomentPost({m}){const[liked,setLiked]=useState(false);return(<div style={{background:T.surface,borderRadius:16,border:`1px solid ${T.border}`,marginBottom:12,overflow:"hidden"}}><div style={{...S.row,gap:10,padding:"10px 14px"}}><div style={{width:32,height:32,borderRadius:8,background:`${T.blue}22`,...S.center,fontSize:16}}>🏪</div><div><div style={{fontSize:13,fontWeight:600,color:T.text}}>{m.by}</div><div style={{fontSize:11,color:T.muted}}>Event moment</div></div></div><div style={{height:200,background:`${m.bg}33`,...S.center,fontSize:64}}>{m.img}</div><div style={{padding:"10px 14px"}}><div style={{...S.row,gap:16,marginBottom:8}}><button onClick={()=>setLiked(!liked)} style={{background:"none",border:"none",cursor:"pointer",fontSize:18}}>{liked?"❤️":"🤍"}</button><span style={{fontSize:18}}>💬</span><span style={{fontSize:18}}>📤</span></div><div style={{fontSize:13,color:T.text,fontWeight:600}}>{liked?m.likes+1:m.likes} likes</div><div style={{fontSize:13,color:T.text,marginTop:4}}><span style={{fontWeight:600}}>{m.by}</span> {m.cap}</div>{m.comments>0&&<div style={{fontSize:12,color:T.muted,marginTop:4}}>View all {m.comments} comments</div>}</div></div>);}
function StatusBar(){return(<div style={{...S.row,justifyContent:"space-between",padding:"8px 20px 4px",color:T.text,fontSize:13,fontWeight:600}}><span>{new Date().toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})}</span><div style={{...S.row,gap:4}}><svg width="16" height="12" viewBox="0 0 16 12"><path d="M1 8h2v4H1zM5 5h2v7H5zM9 3h2v9H9zM13 0h2v12h-2z" fill={T.text}/></svg></div></div>);}

